import stream from 'stream';

const CRLF = '\r\n';

/**
 * Converts a spec-compliant FormData instance to a Node.js stream.
 *
 * @param {FormData} formData
 * @param {import('../core/AxiosHeaders.js').default} headers
 *
 * @returns {stream.Readable}
 */
export default function formDataToStream(formData, headers) {
  const boundary = '--------------------------' + Math.random().toString(16).slice(2) +
    Math.random().toString(16).slice(2);
  const parts = [];
  let contentLength = Buffer.byteLength('--' + boundary + '--' + CRLF);

  const escape = value => String(value).replace(
    /[\r\n"\\]/g,
    char => '%' + char.charCodeAt(0).toString(16).toUpperCase()
  );

  for (const [name, value] of formData) {
    const isBlob = value && (Object.prototype.toString.call(value) === '[object Blob]' ||
      Object.prototype.toString.call(value) === '[object File]');
    const fieldValue = isBlob ? value : String(value);
    const filename = isBlob ? (value.name || 'blob') : undefined;
    const disposition = 'Content-Disposition: form-data; name="' + escape(name) + '"' +
      (filename !== undefined ? '; filename="' + escape(filename) + '"' : '') + CRLF;
    const contentType = isBlob ? 'Content-Type: ' + (value.type || 'application/octet-stream') + CRLF : '';
    const headersBuffer = Buffer.from(
      '--' + boundary + CRLF + disposition + contentType + CRLF,
      'utf8'
    );
    const valueLength = isBlob ? value.size : Buffer.byteLength(fieldValue);
    const part = {
      headers: headersBuffer,
      value: fieldValue,
      isBlob
    };

    parts.push(part);
    contentLength += headersBuffer.length + valueLength + Buffer.byteLength(CRLF);
  }

  contentLength = Number.isFinite(contentLength) ? contentLength : undefined;

  headers.setContentType('multipart/form-data; boundary=' + boundary);
  if (contentLength !== undefined) {
    headers.setContentLength(contentLength);
  }

  return stream.Readable.from((async function *() {
    for (const part of parts) {
      yield part.headers;

      if (part.isBlob) {
        const reader = part.value.stream().getReader();
        try {
          while (true) {
            const result = await reader.read();
            if (result.done) {
              break;
            }
            yield Buffer.from(result.value);
          }
        } finally {
          reader.releaseLock();
        }
      } else {
        yield Buffer.from(part.value, 'utf8');
      }

      yield CRLF;
    }

    yield '--' + boundary + '--' + CRLF;
  })());
}
